#!/bin/sh
# Generated by `pack-tools gen-gates` from packages/pack-tools/templates/gate.sh; do not edit.
#
# Usage: gate.sh <project> [root]
#
# Exits 0 when every artifact this skill's phase requires exists under
# <root>/.singularskills/<folder>/<project>/ (root defaults to the working directory):
# a file must be non-empty, a folder artifact (ending in /) must hold at least one file.
# Otherwise names the missing artifacts on stderr and exits 1.

REQUIRED='01-record.md'
FOLDER='bookkeeping'

if [ -z "$1" ]; then
	echo "usage: gate.sh <project> [root]" >&2
	exit 2
fi
project=$1
root=${2:-.}
dir=$root/.singularskills/$FOLDER/$project

set -f
missing=
for artifact in $REQUIRED; do
	target=$dir/$artifact
	case $artifact in
	*/)
		if [ -d "$target" ] && [ -n "$(find "$target" -type f | head -n 1)" ]; then
			continue
		fi
		;;
	*)
		if [ -f "$target" ] && [ -s "$target" ]; then
			continue
		fi
		;;
	esac
	if [ -z "$missing" ]; then
		missing=$artifact
	else
		missing="$missing, $artifact"
	fi
done

if [ -n "$missing" ]; then
	echo "gate: $project needs $missing first" >&2
	exit 1
fi
exit 0
